// Some portions generated by Claude
import * as cola from 'webcola';
import {computeNetworkLayout} from './graph-layout-network.ts';
import {separateLayoutRectangles} from './graph-layout-overlap.ts';
import {layoutNodeFixed} from './graph-layout-topology.ts';
import type {Graph, PointerPosition} from './graph-types.ts';
import type {LayoutOptions} from './graph-layout-engine.ts';

/** Stress refinement is bounded to the small graph of measured group boxes.
 * Running its dense distance matrix on the full RDF graph is not scalable.
 */
export function computeGroupCenters(graph: Graph, options: LayoutOptions) {
  const initial = computeNetworkLayout(graph, options).positions;
  if (!options.nodeSizes || options.fromCurrent || graph.nodes.some(n => n.pinned) || graph.nodes.length > 80) return initial;
  const nodes = graph.nodes.map(node => ({...initial.get(node.id)!, ...options.nodeSizes!.get(node.id)!}));
  const indices = new Map(graph.nodes.map((node, i) => [node.id, i]));
  const links = graph.edges.map(edge => ({source: indices.get(edge.source)!, target: indices.get(edge.target)!}));
  // The link target follows both endpoint rectangles, not a single global
  // edge length that makes large groups repel each other into distant sectors.
  new cola.Layout().nodes(nodes).links(links).avoidOverlaps(true).handleDisconnected(false)
    .linkDistance(link => {
      const a = nodes[typeof link.source === 'number' ? link.source : link.source.index!];
      const b = nodes[typeof link.target === 'number' ? link.target : link.target.index!];
      return 1.2 * Math.hypot((a.width + b.width) / 2, (a.height + b.height) / 2);
    }).convergenceThreshold(.01).start(40, 60, 120, 0, false);
  const centers = new Map(graph.nodes.map((node, i) => [node.id, {x: nodes[i].x, y: nodes[i].y}]));
  separateLayoutRectangles(graph, centers, {...options, repairOnly: true});
  return centers;
}

/** Reflect whole free groups to bring their boundary members towards the
 * neighboring groups. Reflections preserve card sizes and internal distances;
 * no rotations, resizing, or node-level shuffling of an established map.
 */
export function orientLayoutGroups(graph: Graph, groups: number[][], positions: Map<string, PointerPosition>,
  centers: Map<string, PointerPosition>, options: LayoutOptions = {}) {
  if (options.incremental || options.repairOnly || options.localNodeIds?.size) return;
  const owner = new Map<string, number>(), boundary: Array<Array<{id: string; other: string}>> = groups.map(() => []);
  groups.forEach((members, c) => members.forEach(i => owner.set(graph.nodes[i].id, c)));
  for (const edge of graph.edges) {
    const a = owner.get(edge.source), b = owner.get(edge.target);
    if (a === undefined || b === undefined || a === b) continue;
    boundary[a].push({id: edge.source, other: edge.target});
    boundary[b].push({id: edge.target, other: edge.source});
  }
  for (let pass = 0; pass < 2; pass++) groups.forEach((members, c) => {
    if (members.length < 2 || !boundary[c].length || members.some(i => layoutNodeFixed(graph.nodes[i], options))) return;
    const center = centers.get(String(c))!;
    const energy = (sx: number, sy: number) => boundary[c].reduce((sum, edge) => {
      const p = positions.get(edge.id)!, q = positions.get(edge.other)!;
      return sum + Math.hypot(center.x + (p.x - center.x) * sx - q.x, center.y + (p.y - center.y) * sy - q.y);
    }, 0);
    let best = energy(1, 1), flip = [1, 1];
    for (const [x, y] of [[-1, 1], [1, -1], [-1, -1]]) {
      const cost = energy(x, y);
      if (cost < best - 1e-6) {best = cost; flip = [x, y];}
    }
    for (const i of members) {
      const id = graph.nodes[i].id, p = positions.get(id)!;
      positions.set(id, {x: center.x + (p.x - center.x) * flip[0], y: center.y + (p.y - center.y) * flip[1]});
    }
  });
}
